def compute(vars):
    part = vars["v1"]
    total = vars["v2"]
    if total == 0:
        return None

    value = part / total * 100
    return {
        "value": value,
        "trace": {
            "part": part,
            "total": total,
            "ratio": part / total,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
